    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-007');
});

test('createInvoice rejects an unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

