  applyVoucher(result1.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(result1.value.voucher, undefined);
});

test('invoiceTotals with voucher and discount', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const result2 = applyVoucher(result1.value, { code: 'SAVE10', amount: 5000 });
  const totals = invoiceTotals(result2.value);

  // Subtotal: 95000, Discount: 9500, After discount: 85500
  // VAT: 85500 * 0.21 = 17955
  // Total before voucher: 85500 + 17955 = 103455
  // Total after voucher: 103455 - 5000 = 98455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, 98455);
});

